		["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}, {area:77} 문 앞, 안",
		["{npc:8508}, on the dock"] = "부두의 {npc:8508}",
		["{npc:912}, the warrior trainer"] = "{npc:912}, 전사 상급자",
