		["{skill:171} 75-150: vendor goods"] = "{skill:171} 75-150: 상인 재료",
		["{skill:171} recipes at 135"] = "135에서 {skill:171} 제조법",
		["{skill:171} recipes at 160"] = "160에서 {skill:171} 제조법",
