		["{npc:14904}: {quest:8112}, Exalted"] = "{npc:14904}: {quest:8112}, 확고한 동맹",
		["{npc:14904}: {quest:8116}, Friendly"] = "{npc:14904}: {quest:8116}, 약간 우호적",
		["{npc:14904}: {quest:8116}, Honored"] = "{npc:14904}: {quest:8116}, 우호적",
